// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, random } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ShatterRoadmapProps = Record<string, any>;

const ShatterRoadmap: React.FC<ShatterRoadmapProps> = ({
  backgroundColor = "#0d1117",
  transparentBackground = false,
  durationInSeconds = 5,
  chartGridColor = "#30363d",
  textColor = "#c9d1d9",
  impactIconColor = "#f85149",
  impactLabel = "SALES REQUEST",
  impactFrame = 70,
  bars = [
    { label: "Q1 Architecture", color: "#3b82f6", startPct: 0.05, widthPct: 0.35 },
    { label: "Core API Dev", color: "#8b5cf6", startPct: 0.20, widthPct: 0.40 },
    { label: "User Dashboard", color: "#10b981", startPct: 0.40, widthPct: 0.45 },
    { label: "Data Migration", color: "#f59e0b", startPct: 0.55, widthPct: 0.30 },
    { label: "Public Launch", color: "#ef4444", startPct: 0.75, widthPct: 0.20 }
  ]
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Calculations
  const timelineWidth = width * 0.65;
  const timelineStartX = width * 0.25;
  const topMargin = height * 0.2;
  const rowHeight = height * 0.13;
  const barHeight = height * 0.06;
  
  // Impact Physics Center
  const impactX = timelineStartX + timelineWidth * 0.5;
  const impactY = height * 0.5;
  const t = Math.max(0, frame - impactFrame);
  const snapDelay = 10;

  // Camera Shake
  const shakeIntensity = interpolate(t, [0, 40], [30, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.ease)
  });
  const shakeX = shakeIntensity > 0 ? (random(`shakeX-${frame}`) - 0.5) * shakeIntensity : 0;
  const shakeY = shakeIntensity > 0 ? (random(`shakeY-${frame}`) - 0.5) * shakeIntensity : 0;

  // Icon Drop Math
  const dropStartFrame = Math.max(0, impactFrame - 20);
  const dropY = interpolate(frame, [dropStartFrame, impactFrame], [-height * 0.5, impactY], {
    easing: Easing.in(Easing.exp),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp"
  });

  // Icon Squash/Stretch
  const preImpactStretch = interpolate(frame, [impactFrame - 10, impactFrame], [1, 1.3], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const preImpactSquash = interpolate(frame, [impactFrame - 10, impactFrame], [1, 0.8], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const postImpactScaleX = interpolate(t, [0, 4, 12], [1.5, 0.9, 1], { extrapolateRight: "clamp" });
  const postImpactScaleY = interpolate(t, [0, 4, 12], [0.6, 1.1, 1], { extrapolateRight: "clamp" });
  
  const iconScaleX = t > 0 ? postImpactScaleX : preImpactSquash;
  const iconScaleY = t > 0 ? postImpactScaleY : preImpactStretch;

  // Global Grid Fade
  const gridOpacity = interpolate(t, [0, 15], [0.5, 0], { extrapolateRight: "clamp" });

  // Shockwave Flash
  const flashScale = interpolate(t, [0, 15], [0, 20], { extrapolateRight: "clamp" });
  const flashOpacity = interpolate(t, [0, 15], [0.8, 0], { extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", color: textColor, overflow: "hidden" }}>
      <div style={{ transform: `translate(${shakeX}px, ${shakeY}px)`, width: '100%', height: '100%', transition: 'none' }}>
        
        {/* 1. Grid Lines & Labels */}
        {bars.map((bar, i) => {
          const rowY = topMargin + i * rowHeight;
          const entranceStart = i * 4;
          const entranceEnd = entranceStart + 20;
          const op = interpolate(frame, [entranceStart, entranceEnd], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
          const slideX = interpolate(frame, [entranceStart, entranceEnd], [-30, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp", easing: Easing.out(Easing.cubic) });
          
          const currentOp = t > 0 ? gridOpacity : op; // Grid fades out after impact

          return (
            <React.Fragment key={`grid-${i}`}>
              <div style={{
                position: 'absolute',
                left: width * 0.05 + slideX,
                top: rowY + barHeight/2 - 16,
                fontSize: 24,
                fontWeight: 600,
                opacity: t > 0 ? 1 : op, // Labels stay visible
                transition: 'none'
              }}>
                {bar.label}
              </div>
              <div style={{
                position: 'absolute',
                left: timelineStartX - 20,
                top: rowY + barHeight/2,
                width: timelineWidth + 40,
                height: 2,
                backgroundColor: chartGridColor,
                opacity: currentOp,
                transition: 'none'
              }} />
            </React.Fragment>
          );
        })}

        {/* 2. Roadmap Bars Physics */}
        {bars.map((bar, i) => {
          const rowY = topMargin + i * rowHeight;
          const absStart = timelineStartX + bar.startPct * timelineWidth;
          const absWidth = bar.widthPct * timelineWidth;
          const absEnd = absStart + absWidth;

          const isHit = absStart < impactX && absEnd > impactX;
          
          const entranceStart = i * 4;
          const entranceEnd = entranceStart + 20;
          const entranceOp = interpolate(frame, [entranceStart, entranceEnd], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
          const slideX = interpolate(frame, [entranceStart, entranceEnd], [-50, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp", easing: Easing.out(Easing.cubic) });
          
          const currentSlideX = t > 0 ? 0 : slideX;
          const currentOp = t > 0 ? 1 : entranceOp;

          // Universal fall logic
          const fallGravity = 1.2;

          if (isHit) {
            const leftWidth = impactX - absStart;
            const rightWidth = absEnd - impactX;
            const fallT = Math.max(0, t - snapDelay);

            // Left Piece Physics (Bends down, then detaches and falls)
            const bendRotLeft = interpolate(t, [0, snapDelay], [0, 15 + random(`bend-L-${i}`)*10], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
            const fallRotLeft = fallT * 2;
            const dropYLeft = fallGravity * fallT * fallT;
            const totalRotLeft = bendRotLeft + fallRotLeft;

            // Right Piece Physics
            const bendRotRight = interpolate(t, [0, snapDelay], [0, -(15 + random(`bend-R-${i}`)*10)], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
            const fallRotRight = fallT * -2;
            const dropYRight = fallGravity * fallT * fallT;
            const totalRotRight = bendRotRight + fallRotRight;

            return (
              <React.Fragment key={`bar-hit-${i}`}>
                {/* Left Broken Half */}
                <div style={{
                  position: 'absolute',
                  left: absStart + currentSlideX,
                  top: rowY,
                  width: leftWidth,
                  height: barHeight,
                  overflow: 'hidden',
                  borderRadius: `${barHeight/2}px 0 0 ${barHeight/2}px`,
                  transformOrigin: 'left center',
                  transform: `translate(0px, ${dropYLeft}px) rotate(${totalRotLeft}deg)`,
                  opacity: currentOp,
                  transition: 'none',
                  boxShadow: t > 0 ? 'none' : '0 10px 20px rgba(0,0,0,0.3)'
                }}>
                  <div style={{ width: absWidth, height: '100%', backgroundColor: bar.color }} />
                </div>

                {/* Right Broken Half */}
                <div style={{
                  position: 'absolute',
                  left: impactX + currentSlideX,
                  top: rowY,
                  width: rightWidth,
                  height: barHeight,
                  overflow: 'hidden',
                  borderRadius: `0 ${barHeight/2}px ${barHeight/2}px 0`,
                  transformOrigin: 'right center',
                  transform: `translate(0px, ${dropYRight}px) rotate(${totalRotRight}deg)`,
                  opacity: currentOp,
                  transition: 'none',
                  boxShadow: t > 0 ? 'none' : '0 10px 20px rgba(0,0,0,0.3)'
                }}>
                  <div style={{
                    position: 'absolute',
                    left: -leftWidth, // Shift content cleanly to maintain original alignment
                    top: 0,
                    width: absWidth,
                    height: '100%',
                    backgroundColor: bar.color
                  }} />
                </div>
              </React.Fragment>
            );
          } else {
            // Intact bar reacting to the shockwave
            const dist = Math.abs((absStart + absWidth/2) - impactX);
            const shockDelay = snapDelay + dist * 0.04;
            const fallT = Math.max(0, t - shockDelay);
            const dropY = fallGravity * fallT * fallT;
            const dir = (absStart + absWidth/2) < impactX ? -1 : 1;
            const rot = dir * fallT * 1.5;

            return (
              <div key={`bar-intact-${i}`} style={{
                position: 'absolute',
                left: absStart + currentSlideX,
                top: rowY,
                width: absWidth,
                height: barHeight,
                backgroundColor: bar.color,
                borderRadius: barHeight / 2,
                transform: `translate(0px, ${dropY}px) rotate(${rot}deg)`,
                transformOrigin: dir === -1 ? 'left center' : 'right center',
                opacity: currentOp,
                transition: 'none',
                boxShadow: t > shockDelay ? 'none' : '0 10px 20px rgba(0,0,0,0.3)'
              }} />
            );
          }
        })}

        {/* 3. Shockwave Flash */}
        {t > 0 && t <= 15 && (
          <div style={{
            position: 'absolute',
            left: impactX - 50,
            top: impactY - 50,
            width: 100,
            height: 100,
            borderRadius: '50%',
            backgroundColor: 'white',
            transform: `scale(${flashScale})`,
            opacity: flashOpacity,
            zIndex: 5,
            transition: 'none'
          }} />
        )}

        {/* 4. The "Sales Request" Slam Icon */}
        <div style={{
          position: 'absolute',
          left: impactX - 75,
          top: dropY - 75,
          width: 150,
          height: 150,
          backgroundColor: impactIconColor,
          borderRadius: 30,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          boxShadow: '0 40px 80px rgba(0,0,0,0.8), inset 0 8px 16px rgba(255,255,255,0.3)',
          transform: `scale(${iconScaleX}, ${iconScaleY})`,
          transformOrigin: 'center bottom',
          zIndex: 10,
          transition: 'none'
        }}>
          <span style={{ color: 'white', fontSize: 100, fontWeight: 900, transform: 'translateY(-5px)', textShadow: '0 4px 10px rgba(0,0,0,0.3)' }}>!</span>
          
          {/* Label tied to the icon */}
          <div style={{
            position: 'absolute',
            top: '100%',
            marginTop: 30,
            width: 500,
            left: '50%',
            transform: 'translateX(-50%)',
            textAlign: 'center',
            color: impactIconColor,
            fontSize: 36,
            fontWeight: 800,
            letterSpacing: 2,
            textShadow: '0 10px 20px rgba(0,0,0,0.6)',
            opacity: frame > impactFrame - 20 ? 1 : 0,
            transition: 'none'
          }}>
            {impactLabel}
          </div>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default ShatterRoadmap;